const $=id=>document.getElementById(id);let data=[],isDemo=true,logoURL=null;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dateFr=s=>s.split('-').reverse().join('/');const duration=n=>Math.floor(Math.round(n)/60)+' h '+String(Math.round(n)%60).padStart(2,'0');function message(t,error=false){$('message').textContent=t;$('message').className=error?'error':'';}function selection(){return data.filter(r=>(!$('client').value||r.client===$('client').value)&&(!$('from').value||r.date>=$('from').value)&&(!$('to').value||r.date<=$('to').value));}function render(){const invalid=$('from').value&&$('to').value&&$('from').value>$('to').value;$('print').disabled=!!invalid;if(invalid)message('La date de début doit précéder la date de fin.',true);else message(data.length+' interventions chargées.');const rows=invalid?[]:selection().sort((a,b)=>a.date.localeCompare(b.date));const s=RapportCore.summarize(rows);$('reportCompany').textContent=$('company').value.trim()||'Votre entreprise';$('footerCompany').textContent=$('reportCompany').textContent;$('reportClient').textContent=$('client').value||'Tous les clients';$('period').textContent=($('from').value?'Du '+dateFr($('from').value):'Toutes dates')+($('to').value?' au '+dateFr($('to').value):'');$('count').textContent=s.count;$('duration').textContent=duration(s.minutes);$('resolved').textContent=s.resolved;$('rows').innerHTML=rows.map(r=>'<tr><td>'+dateFr(r.date)+'<small>'+esc(r.client)+'</small></td><td>'+esc(r.intervention)+'</td><td>'+duration(r.minutes)+'</td><td><span class="status '+(r.statut==='Résolu'?'done':'pending')+'">'+r.statut+'</span></td></tr>').join('');$('empty').hidden=rows.length>0;$('demoBadge').hidden=!isDemo;$('source').textContent=isDemo?'Données fictives de démonstration':'Vos données · session locale';$('reportNote').textContent=$('note').value;$('noteBox').hidden=!$('note').value.trim();}
function load(text,demo){const next=RapportCore.parseCSV(text);data=next;isDemo=demo;const clients=[...new Set(data.map(r=>r.client))].sort();$('client').innerHTML='<option value="">Tous les clients</option>'+clients.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('');if(demo)$('client').value=clients[0];const dates=data.map(r=>r.date).sort();$('from').value=dates[0];$('to').value=dates.at(-1);render();return RapportCore.summarize(data);}
const demoText=`date;client;intervention;duree_minutes;statut
2026-09-02;Cabinet Horizon;Mise à jour des postes de travail;90;Résolu
2026-09-05;Cabinet Horizon;Configuration de la sauvegarde quotidienne;120;Résolu
2026-09-09;Cabinet Horizon;Diagnostic de la connexion réseau;45;Résolu
2026-09-12;Cabinet Horizon;Remplacement du poste d’accueil;60;En cours
2026-09-16;Cabinet Horizon;Contrôle des restaurations de sauvegarde;30;Résolu
2026-09-18;Cabinet Horizon;Migration de la messagerie;0;À planifier
2026-09-04;Studio Martin;Installation d’une imprimante réseau;45;Résolu
2026-09-14;Studio Martin;Maintenance préventive;60;Résolu`;
$('demo').onclick=()=>{load(demoText,true);$('file').value='';};$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2*1024*1024)throw Error('Fichier trop volumineux : maximum 2 Mo.');load(await f.text(),false);}catch(err){message(err.message+' Le rapport précédent est conservé.',true);}finally{e.target.value='';}};['company','client','from','to','note'].forEach(id=>$(id).addEventListener('input',render));$('print').onclick=()=>window.print();$('logo').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>500*1024){message('Choisissez un PNG ou JPEG de 500 Ko maximum.',true);e.target.value='';return;}const url=URL.createObjectURL(f),img=new Image();img.onload=()=>{if(logoURL)URL.revokeObjectURL(logoURL);logoURL=url;$('reportLogo').src=url;$('reportLogo').hidden=false;$('symbol').hidden=true;};img.onerror=()=>{URL.revokeObjectURL(url);message('Image illisible.',true);};img.src=url;};$('removeLogo').onclick=()=>{if(logoURL)URL.revokeObjectURL(logoURL);logoURL=null;$('logo').value='';$('reportLogo').hidden=true;$('reportLogo').removeAttribute('src');$('symbol').hidden=false;};load(demoText,true);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'import_interventions_csv',title:'Importer des interventions',description:'Remplace les données du rapport visible avec un CSV validé. Traitement local.',inputSchema:{type:'object',properties:{csv:{type:'string',maxLength:2000000}},required:['csv'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(typeof input?.csv!=='string'||input.csv.length>2000000)throw Error('CSV texte requis, 2 Mo maximum.');return load(input.csv,false);}})).catch(()=>{});}catch{}}
